  JOIN vocab_words w ON lower(w.headword) = v.headword
ON CONFLICT (word_id, sort_order) DO UPDATE
  SET collocation    = EXCLUDED.collocation,
      sentence       = EXCLUDED.sentence,
      translation_zh = EXCLUDED.translation_zh,
      scene          = EXCLUDED.scene;

SELECT 'AFTER' AS stage,
       (SELECT count(*) FROM vocab_words WHERE def_zh IS NOT NULL) AS words_with_def,
       (SELECT count(*) FROM vocab_examples) AS examples;

-- ── 断言:**只判本批这 378 个词**,不判全表 ────────────────────
-- ⚠️ 原来写的是 (SELECT count(*) FROM vocab_words WHERE def_zh IS NOT NULL) = 本批词数。
--    那在只有托福一个库时碰巧成立,多几个库以后必然为 f —— 全表里还有别的库的词。
--    判据必须锁在本批范围内(见 batch-validate-scope-to-batch)。
-- ⚠️ 用 DO + RAISE:断言不过**直接抛异常整笔回滚**,不靠人眼看那几个 t/f。
DO $gate$
DECLARE
  n_missing int; n_badcount int; n_badscene int;
BEGIN
  SELECT count(*) INTO n_missing
    FROM (VALUES
  ('million', '/ˈmɪl.jən/', '百万', 'The cardinal number equal to one thousand thousand.'),
  ('case', '/keɪs/', '案例；情况', 'A particular situation or example of something.'),
  ('better', '/ˈbɛtər/', '更好的；较好的', 'Of a higher quality or more desirable.'),
  ('matter', '/ˈmæt.ər/', '事情；物质', 'A subject or situation under consideration or discussion.'),
  ('simply', '/ˈsɪm.pli/', '简单地；仅仅', 'In a straightforward or uncomplicated manner.'),
  ('certainly', '/ˈsɜːr.tən.li/', '当然；肯定', 'In a way that is definite or certain.'),
  ('per', '/pɜr/', '每；每一', 'For each; for every; used in measurements or rates.'),
  ('subject', '/ˈsʌb.dʒɛkt/', '主题；科目', 'A topic or area of study, often in education.'),
  ('usually', '/ˈjuː.ʒuː.əli/', '通常', 'In most cases; as a rule.'),
  ('ahead', '/əˈhɛd/', '在前；向前', 'In a forward position or direction; in advance.'),
  ('recognise', '/ˈrɛk.əɡ.naɪz/', '认出；识别', 'To identify someone or something from previous encounters.'),
  ('blue', '/bluː/', '蓝色', 'A color between green and violet on the spectrum.'),
  ('credit', '/ˈkrɛd.ɪt/', '信用；信誉', 'The ability to borrow money or receive goods with trust.'),
  ('flight', '/flaɪt/', '航班', 'A journey made by air, especially in an aircraft.'),
  ('block', '/blɑk/', '阻碍；街区', 'To obstruct or stop movement; a solid piece.'),
  ('bear', '/bɛr/', '忍受；承受', 'To endure or tolerate something difficult or unpleasant.'),
  ('works', '/wɜrks/', '工作；作品', 'Things produced as a result of effort or activity.'),
  ('straight', '/streɪt/', '直的；正直的', 'Not curving or bending; direct or honest.'),
